return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T12:05:05+00:00','po-revision-date'=>'2026-09-26T12:05:05+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Podstawowe wydanie przebudowanego Page Builder Sandwich: ekran ustawień i informacji, warstwa wyjściowa front-endu bez śladów SEO oraz jeden przykładowy blok zawartości.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Dostawcy sztucznej inteligencji','The makers of ChatGPT. A good all-rounder.'=>'Twórcy ChatGPT. Dobry wszechstronny wybór.','The makers of Claude. Strong at writing and careful reasoning.'=>'Twórcy Claude. Silni w pisaniu i ostrożni w rozumowaniu.','Google\'s Gemini models. Fast and inexpensive.'=>'Modele Gemini od Google. Szybkie i tanie.','A European AI company with fast, inexpensive models.'=>'Europejska firma zajmująca się sztuczną inteligencją, oferująca szybkie i niedrogie modele.','Low-cost models that are good at writing and code.'=>'Niedrogie modele świetnie radzące sobie z pisaniem i kodowaniem.','One key for models from many different providers.'=>'Jednen klucz do modeli od wielu różnych dostawców.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Dowolna usługa działająca tak samo jak interfejs API OpenAI, w tym model uruchomiony na własnym komputerze lub serwerze.','General (used when nothing more specific is set)'=>'Ogólne (stosowane, gdy nie ustawiono nic bardziej szczegółowego)','Writing and rewriting'=>'Zapisywanie i ponowne zapisywanie','Translation'=>'Tłumaczenie','Code and CSS'=>'Kod i CSS','Sorry, you are not allowed to access this page.'=>'Przepraszamy, nie masz uprawnień do uzyskania dostępu do tej strony.','These settings are shared by every plugin that uses them: %s.'=>'Te ustawienia są wspólne dla każdej wtyczki, która z nich korzysta: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Klucze są szyfrowane w bazie danych tej witryny i są wysyłane wyłącznie do wybranego przez Państwa dostawcy – nigdy do nas.','Step 1 of 2: choose an AI provider'=>'Krok 1 z 2: wybierz dostawcę AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Używasz własnego klucza, więc płacisz dostawcy bezpośrednio za to, z czego korzystasz. Nie masz pewności? Każda z tych opcji sprawdza się dobrze; w przyszłości możesz dodać kolejne.','Next'=>'Dalej','Step 2 of 2: connect %s'=>'Krok 2 z 2: połącz z %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Wprowadź adres swojej usługi kompatybilnej z OpenAI, kończący się na /v1. Klucz jest wymagany tylko wtedy, gdy usługa go żąda.','Open %s and sign in (or create a free account).'=>'Otwórz %s i zaloguj się (lub utwórz darmowe konto).','the %s API keys page'=>'strona kluczy API %s','Create a new key and copy it.'=>'Utwórz nowy klucz i skopiuj go.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Wklej go poniżej i kliknij „Zapisz i przetestuj”. Wyślemy jedno małe żądanie, aby sprawdzić, czy działa.','Most providers need a little credit on the account before a key works: %s.'=>'Większość dostawców wymaga niewielkich środków na koncie, zanim klucz zacznie działać: %s.','add credit'=>'dodaj środki kredytowe','← Choose a different provider'=>'← Wybierz innego dostawcę','Address'=>'Adres','Saved key ends in …%s — paste a new one to replace it'=>'Zapisany klucz kończy się na …%s — wklej nowy, aby go zastąpić','Key (optional)'=>'Klucz (opcjonalnie)','API key'=>'Klucz API','Save and test'=>'Zapisz i przetestuj','Providers'=>'Dostawcy','Provider'=>'Dostawca','Status'=>'Status','Key'=>'Klucz','Get a key'=>'Pobierz klucz','Test'=>'Test','Remove'=>'Usuń','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Zapisano przy użyciu nowszej wersji wtyczki: zaktualizuj tę wtyczkę lub wprowadź klucz ponownie.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Zapisanego klucza nie można już otworzyć (klucze zabezpieczeń witryny uległy zmianie). Wprowadź go ponownie.','Not connected'=>'Niepodłączony','Connected — last test passed %s'=>'Połączono — ostatni test zaliczony %s','Last test failed: %s'=>'Ostatni test nie powiódł się: %s','Connected — not tested yet'=>'Połączono — jeszcze nie przetestowano','Which model to use'=>'Który model użyć','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ oznacza nasze zalecenie dla tego zadania. Lista zawiera każdy model, z którego może korzystać Twój klucz, pobierany na żywo od dostawcy.','— Recommended for the provider —'=>'— Polecane przez dostawcę —','Save models'=>'Zapisz modele','Refresh the model lists from the providers'=>'Odśwież listy modeli od dostawców','best quality'=>'najwyższa jakość','lowest cost'=>'najniższy koszt','fastest'=>'najszybsze','Add a model yourself'=>'Dodaj model samodzielnie','A model came out today? Paste its exact name to use it straight away.'=>'Pojawił się nowy model? Wklej jego dokładną nazwę, aby móc od razu z niego skorzystać.','Model name'=>'Nazwa modelu','Add model'=>'Dodaj model','Recommended models list'=>'Lista polecanych modeli','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Nie udało się zweryfikować listy polecanych modeli, więc nie wyświetlono żadnych rekomendacji. Zainstaluj ponownie wtyczkę lub włącz codzienne aktualizacje poniżej.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Używana lista została opublikowana %s. Każda aktualizacja wtyczki wprowadza nową.','Also check Zinn Digital® once a day for an updated list.'=>'Sprawdzaj również Zinn Digital® raz dziennie, aby uzyskać zaktualizowaną listę.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Wysyłane jest wyłącznie zwykłe żądanie pobrania: brak klucza, adresu strony i jakichkolwiek informacji o treści. Lista jest podpisana, a lista, która nie przejdzie pomyślnie weryfikacji podpisu, jest ignorowana.','Last checked %1$s: %2$s.'=>'Ostatnie sprawdzenie %1$s: %2$s.','Save, and check now if turned on'=>'Zapisz i sprawdź teraz, jeśli włączono','a newer list was installed'=>'zainstalowano nowszą listę','already up to date'=>'najnowsza wersja','the download failed the signature check and was ignored'=>'pobieranie nie powiodło się, ponieważ sprawdzanie sygnatury zakończyło się niepowodzeniem, i plik został zignorowany','Zinn Digital® could not be reached; the current list stays in use'=>'Nie można było połączyć się z Zinn Digital®; bieżąca lista pozostaje w użyciu','turned off'=>'wyłączone','Open'=>'Otwórz','Check their status page'=>'Sprawdź ich stronę statusu','Open your billing page'=>'Otwórz stronę rozliczeniową','Open your API keys page'=>'Otwórz stronę kluczy API','Open the AI settings'=>'Otwórz ustawienia AI','Sorry, you are not allowed to do that.'=>'Przepraszamy, nie masz do tego uprawnień.','Unknown provider.'=>'Nieznany dostawca.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Wprowadź adres swojego serwisu, na przykład http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To nie wygląda na klucz API. Skopiuj go ponownie, bez spacji.','Paste your API key first.'=>'Najpierw wklej swój klucz API.','Key removed.'=>'Klucz usunięty.','Models saved.'=>'Zapisano modele.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Wpisz dokładną nazwę modelu, na przykład tak, jak jest podana w dokumentacji dostawcy.','Added %s. Choose it under "Which model to use".'=>'Dodano %s. Wybierz go w sekcji „Którego modelu użyć”.','Model removed.'=>'Model usunięty.','Daily updates are off. The list that came with the plugin is used.'=>'Codzienne aktualizacje są wyłączone. Używana jest lista dostarczona wraz z wtyczką.','Checked: %s.'=>'Zaznaczono: %s.','Model lists refreshed.'=>'Odświeżono listy modeli.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Twój klucz AI został zapisany przez nowszą wersję jednej z Twoich wtyczek. Zaktualizuj tę wtyczkę lub wprowadź klucz ponownie w ustawieniach AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Twój zapisany klucz AI nie może być już odczytany (klucze bezpieczeństwa witryny uległy zmianie). Wprowadź go ponownie w ustawieniach AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Sztuczna inteligencja nie jest jeszcze skonfigurowana. Dodaj klucz dostawcy sztucznej inteligencji w ustawieniach AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Nie wybrano modelu dla tego zadania. Wybierz jeden w ustawieniach sztucznej inteligencji.','That AI provider is not supported by this version of the plugin.'=>'Ten dostawca sztucznej inteligencji nie jest obsługiwany przez tę wersję wtyczki.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ta witryna nie mogła połączyć się z Twoją usługą AI. Sprawdź, czy jest ona uruchomiona i czy jej adres jest osiągalny z serwera WWW (usługa na Twoim własnym komputerze nie jest osiągalna z hostowanej witryny).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ta witryna nie mogła połączyć się z %s. Sprawdź jej stronę statusu; jeśli działa, Twój hosting może blokować połączenia wychodzące lub adres jest błędny.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s informuje, że Twoje konto nie ma już środków ani limitu. Dodaj środki lub zwiększ limit na swoim koncie u tego dostawcy, a następnie spróbuj ponownie.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nie zaakceptował(a) Twojego klucza. Mogł(a)by być błędnie wpisany, unieważniony lub wygasły. Utwórz nowy klucz i wklej go tutaj.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s odrzuciło to żądanie dotyczące Twojego klucza. Klucz może nie mieć dostępu do tego modelu lub funkcji bądź Twoje konto wymaga weryfikacji.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model „%1$s” nie jest dostępny w usłudze %2$s dla Twojego klucza. Wybierz inny model w ustawieniach AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Twój plan %2$s nie zawiera modelu „%1$s”. Wybierz inny model w ustawieniach sztucznej inteligencji lub uaktualnij swój plan u nich.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ogranicza szybkość wysyłania żądań przez klucz. Odczekaj chwilę i spróbuj ponownie lub zwiększ u nich limit zapytań.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s ma obecnie problemy (awaria lub przeciążenie po ich stronie). Twoje ustawienia są w porządku. Spróbuj ponownie za chwilę.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Żądanie AI nie powiodło się z nieznanej przyczyny. Spróbuj ponownie; jeśli problem będzie się powtarzał, skontaktuj się z pomocą techniczną, podając poniższe szczegóły.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Dostawca sztucznej inteligencji odpowiedział wformacie, którego ta wtyczka nie mogła odczytać. Spróbuj ponownie; jeśli problem będzie się powtarzał, wybierz inny model lub skontaktuj się z pomocą techniczną.','Custom (OpenAI-compatible)'=>'Niestandardowy (zgodny z OpenAI)','Save a key for this provider first.'=>'Najpierw zapisz klucz dla tego dostawcy.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Twój klucz działa, ale dostawca nie podaje dla niego żadnego modelu tekstowego. Dodaj model samodzielnie poniżej.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Połączono. Użytkownik %1$s odpowiedział za pomocą %2$s. Funkcje sztucznej inteligencji są gotowe do użycia.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Twoja rola użytkownika nie ma uprawnień do korzystania ze sztucznej inteligencji w tej witrynie. Skontaktuj się z administratorem.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ta strona osiągnęła miesięczny limit wydatków na sztuczną inteligencję. Administrator może go zwiększyć w ustawieniach sztucznej inteligencji.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ta witryna osiągnęła miesięczny limit żądań AI. Administrator może go zwiększyć w ustawieniach AI.','Usage and cost'=>'Użycie i koszty','The log, limits and role permissions apply to AI used through: %s.'=>'Dziennik, limity i uprawnienia ról dotyczą sztucznej inteligencji używanej za pośrednictwem: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Koszty są szacunkowe i zostały obliczone na podstawie opublikowanych cen; model o nieznanej cenie liczy się jako zero.','This month: %1$s requests, about %2$s.'=>'W tym miesiącu: %1$s żądań, około %2$s.','When'=>'Kiedy','Who'=>'Kto','Used for'=>'Używane do','Model'=>'Model','Tokens in / out'=>'Tokeny wejścia / wyjścia','About'=>'O programie','Result'=>'Wynik','No AI requests have been made yet.'=>'Nie wykonano jeszcze żadnych żądań AI.','Done'=>'Gotowe','Limits and permissions'=>'Limity i uprawnienia','Monthly spending limit (US dollars)'=>'Miesięczny limit wydatków (USD)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Pozostaw puste, aby usunąć limit. Sztuczna inteligencja przestanie działać do końca miesiąca, gdy szacowany koszt go osiągnie.','Monthly request limit'=>'Miesięczny limit żądań','Leave empty for no limit.'=>'Pozostaw puste, aby nie wprowadzać limitu.','Who may use AI'=>'Kto może korzystać ze sztucznej inteligencji','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Zaznacz opcję „żadne”, aby pozwolić wszystkim osobom mogącym korzystać z funkcji wtyczki na korzystanie ze sztucznej inteligencji. Administratorzy mogą z niej korzystać zawsze.','Save limits and permissions'=>'Zapisz limity i uprawnienia','Limits and permissions saved.'=>'Limity i uprawnienia zostały zapisane.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skrypty ekranu administratora są niedostępne w tej kopii wtyczki. Zainstaluj ją ponownie z oficjalnego pakietu.','This screen needs JavaScript.'=>'Ten ekran wymaga obsługi JavaScript.','Languages'=>'Języki','Upgrade'=>'Uaktualnij','Pricing'=>'Cennik','Start Trial'=>'Rozpocznij okres próbny','Account'=>'Konto','Contact Us'=>'Skontaktuj się z nami','Affiliation'=>'Powiązanie','the kind of softwarePlugin'=>'Wtyczka','greetingHey %s,'=>'Witaj %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Zapisz się, aby otrzymywać powiadomienia e-mail dotyczące aktualizacji zabezpieczeń i funkcji, materiałów edukacyjnych oraz okazjonalnych ofert, a także aby udostępnić podstawowe informacje o środowisku WordPress. Pomoże nam to uczynić %s bardziej kompatybilnym z Twoją witryną i lepiej dostosowanym do Twoich potrzeb.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Zapisz się, aby otrzymywać powiadomienia e-mail dotyczące aktualizacji zabezpieczeń i funkcji, materiałów edukacyjnych oraz okazjonalnych ofert, a także aby udostępnić podstawowe informacje o środowisku WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Jeśli to pominiesz, w porządku! %1$s nadal będzie działać bez zarzutu.','Allow & Continue'=>'Zezwól i kontynuuj','verbSkip'=>'Pomiń','Skipping, please wait'=>'Pominięcie, proszę czekać','Continue'=>'Kontynuuj','Please wait'=>'Proszę czekać','as activating pluginActivating'=>'Aktywowanie','This will allow %s to'=>'To umożliwi %s','Privacy Policy'=>'Polityka prywatności','Terms of Service'=>'Warunki korzystania z usługi','License Agreement'=>'Umowa licencyjna','Have a license key?'=>'Masz klucz licencyjny?','Activate License'=>'Aktywuj licencję','View Basic Profile Info'=>'Wyświetl podstawowe informacje profilu','Your WordPress user\'s: first & last name, and email address'=>'Imię i nazwisko oraz adres e-mail użytkownika WordPressa','View Basic Website Info'=>'Wyświetl podstawowe informacje o witrynie','Homepage URL & title, WP & PHP versions, and site language'=>'Adres URL i tytuł strony głównej, wersje WP i PHP oraz język witryny','View Basic %s Info'=>'Wyświetl podstawowe informacje o %s','Current %s & SDK versions, and if active or uninstalled'=>'Aktualne wersje %s i SDK oraz informacja, czy są aktywne czy odinstalowane','Newsletter'=>'Biuletyn','Updates, announcements, marketing, no spam'=>'Aktualizacje, ogłoszenia, marketing, zero spamowania','View Diagnostic Info'=>'Wyświetl informacje diagnostyczne','WordPress & PHP versions, site language & title'=>'Wersje WordPress i PHP, język i tytuł witryny','View Plugins & Themes List'=>'Wyświetl listę wtyczek i motywów','Names, slugs, versions, and if active or not'=>'Nazwy, uproszczone nazwy (slugi), wersje oraz informacje o tym, czy element jest aktywny','optional'=>'opcjonalne','Never miss an important update'=>'Nigdy nie przegap ważnej aktualizacji','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Wprowadziliśmy tę opcję, aby nie ominęła Państwa żadna ważna aktualizacja i aby pomóc nam w dostosowaniu %s do Państwa witryny oraz w lepszym spełnianiu Państwa potrzeb.','Thank you for updating to %1$s v%2$s!'=>'Dziękujemy za zaktualizowanie do %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Przedrostek musi składać się z od 1 do 8 małych liter lub cyfr, zaczynać się od litery i nie może pokrywać się z nazwą wtyczki.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Stworzone przez Neil Lock, CEO Zinn Digital® Ltd','Version %s'=>'Wersja %s','Page Builder Sandwich website'=>'Strona internetowa Page Builder Sandwich','Zinn Digital® website'=>'Strona internetowa Zinn Digital®','Settings saved.'=>'Zapisano ustawienia.','See the Pro plans and pricing'=>'Zobacz plany Pro i cennik','Front-end output'=>'Wyjście front-endu','Class name prefix'=>'Prefiks nazwy klasy','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Każda nazwa klasy, którą wtyczka umieszcza na Twoich stronach, zaczyna się od tego prefisku, dzięki czemu strony nie zdradzają, która wtyczka je utworzyła. Od 1 do 8 małych liter lub cyfr, zaczynając od litery.','Save'=>'Zapisz','Beta updates'=>'Aktualizacje beta','This site receives beta versions as updates.'=>'Ta witryna otrzymuje wersje beta jako aktualizacje.','This site receives stable versions only.'=>'Ta witryna otrzymuje tylko stabilne wersje.','Change this on the Account page'=>'Zmień to na stronie Konta','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Wersje beta są oferowane licencjonowanym instalacjom Pro połączonym z ich kontem. Po połączeniu możesz dołączyć ze strony Konta.','Content'=>'Treść','Heading'=>'Nagłówek','Text'=>'Tekst','Style'=>'Styl','Plain'=>'Zwykły','Accent'=>'Wyróżnienie','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Brak języków do wyboru. Przełącznik pojawia się, gdy wtyczka tłumaczenia zawiera co najmniej dwa języki.','Switcher'=>'Przełącznik','Accessible label'=>'Etykieta dostępności','Show the current language'=>'Pokaż bieżący język','block titleLanguage switcher (sample)'=>'Przełącznik języka (przykładowy)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Wyświetla języki witryny z wtyczki tłumaczenia, gdy jest ona aktywna. W przeciwnym razie nic nie renderuje.','block keywordlanguage'=>'Język','block keywordswitcher'=>'Przełącznik','block titleSample content'=>'Przykładowa treść','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Nagłówek i akapit wyrenderowane z neutralnymi nazwami klas. Stanowią one blok odniesienia dla umowy tłumaczeniowej.','block keywordsample'=>'próbka','block keywordtext'=>'tekst']];